package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		n := scanner.Text()
		a := 0
		for _, r := range n {
			if r == 'a' {
				a++
			}
		}
		if a > len(n)/2 {
			fmt.Println(len(n))
		} else {
			fmt.Println(a + (a - 1))
		}
	}
}

